/**
 * Resolve the current workspace from a URL pathname.
 *
 * Uses ModRegistry.getWorkspaces() to match the pathname against registered
 * workspace references. Canonical URLs use `/w/{vendor}/{mod}/{workspace}/{displayId}`;
 * legacy first-party URLs are accepted while redirects are generated by Router.
 *
 * Lifted from bundled/tabs/ so both tabs and mentions can share it.
 */
import { ModRegistry } from "./ModRegistry";
import type { CurrentWorkspace } from "./types";

/**
 * Extract a workspace ID from a URL path, if the first segment matches
 * a registered workspace. Returns null when no workspace matches.
 *
 * Works for both full paths (`/lims/BLOOD1`) and bare workspace paths
 * (`/lims`), so it serves both `resolveCurrentWorkspace` and sidebar
 * icon derivation from tab URLs.
 */
export function extractWorkspaceId(url: string): string | null {
  const workspaces = ModRegistry.getInstance().getWorkspaces();
  const parts = url.split("?")[0].split("/").filter(Boolean).map(decodeURIComponent);
  if (parts[0] === "w" && parts.length >= 5) {
    const reference = `${parts[1]}.${parts[2]}:${parts[3]}`;
    for (const [workspaceId, config] of workspaces) {
      if (config.reference.id === reference) return workspaceId;
    }
  }
  for (const [workspaceId, config] of workspaces) {
    if (url.startsWith(`/${config.reference.workspace}/`) || url === `/${config.reference.workspace}`) {
      return workspaceId;
    }
  }
  return null;
}

export function resolveCurrentWorkspace(
  pathname: string,
): CurrentWorkspace | null {
  const workspaceId = extractWorkspaceId(pathname);
  if (!workspaceId) return null;

  const parts = pathname.split("?")[0].split("/").filter(Boolean).map(decodeURIComponent);
  const isCanonical = parts[0] === "w";
  const displayId = isCanonical ? parts[4] : parts[1];
  if (!displayId) return null;
  const config = ModRegistry.getInstance().getWorkspaces().get(workspaceId);
  if (!config) return null;

  return {
    reference: config.reference,
    displayId,
    url: pathname,
    icon: config.reference.workspace,
  };
}
